import fs from 'node:fs';import path from 'node:path';import os from 'node:os';import {spawnSync} from 'node:child_process';import {pathToFileURL} from 'node:url';
const repo=process.cwd(); const runner=path.join(repo,'scripts','verify-cf05-ui-live.mjs'); const parent=path.resolve(repo,'.tmp'); fs.mkdirSync(parent,{recursive:true}); const owned=fs.mkdtempSync(path.join(parent,'cons03-audit-')); const ownedReal=fs.realpathSync(owned); const report={};
try {
 const env={...process.env,DEMO_USER_PASSWORD:'SyntheticAuditFixture',RUNNER_DRY_RUN:'true',CHROME_BIN:process.execPath,CHROME_PATH:'',RUN_ID:'same-run'};
 const run=()=>spawnSync(process.execPath,[runner],{cwd:owned,env,encoding:'utf8',timeout:5000,windowsHide:true});
 const first=run(); const dir=path.join(owned,'docs/audit/evidence/runs/same-run');const manifest=path.join(dir,'manifest.json');const firstManifest=JSON.parse(fs.readFileSync(manifest,'utf8'));fs.writeFileSync(manifest,'SENTINEL: PRESERVE EXISTING EVIDENCE');const second=run();
 report.duplicateRun={firstExit:first.status,secondExit:second.status,sentinelPreserved:fs.readFileSync(manifest,'utf8')==='SENTINEL: PRESERVE EXISTING EVIDENCE',firstManifest};
 // Traversal remains inside the disposable audit root; never targets project evidence.
 const traversal=spawnSync(process.execPath,[runner],{cwd:owned,env:{...env,RUN_ID:'../escaped'},encoding:'utf8',timeout:5000,windowsHide:true}); report.traversal={exit:traversal.status,writtenOutsideRuns:fs.existsSync(path.join(owned,'docs/audit/evidence/escaped/manifest.json'))};
 delete process.env.RUN_ID;delete process.env.RUNNER_DRY_RUN;delete process.env.RUN_SCREENSHOTS_DIR;
 process.chdir(owned);const mod=await import(pathToFileURL(runner).href);const calls=[];mod.ChromeInstance.prototype.start=async()=>{throw new Error('Synthetic UI failure; no browser spawned')};mod.ChromeInstance.prototype.stop=async function(){calls.push(this.profilePrefix);if(this.profilePrefix==='ui_profile_a')throw new Error('[RESOURCE_LEAK_DETECTED]: synthetic first-instance failure')};try{await mod.main()}catch(e){report.cleanup={stopCalls:calls,rejection:e.message};}
 process.env.CHROME_BIN=path.join(owned,'absent-chrome.exe');delete process.env.CHROME_PATH;try{report.explicitMissingChrome={resolved:mod.resolveChromePath(),rejected:false}}catch(e){report.explicitMissingChrome={rejected:true,message:e.message}}
} finally { process.chdir(repo);if(fs.realpathSync(owned)!==ownedReal||path.dirname(ownedReal)!==fs.realpathSync(parent)||!path.basename(ownedReal).startsWith('cons03-audit-'))throw new Error('Cleanup path boundary failed');fs.rmSync(ownedReal,{recursive:true,force:true}); report.cleanupOwnedDirectory=!fs.existsSync(ownedReal);}
console.log('AUDIT_JSON='+JSON.stringify(report));
